// Analyze repository health and prepare data for Claude
const repoData = $input.item(0).json;
const commitsData = $input.item(1).json;

const now = new Date();
const repoName = repoData.name;

let healthScore = 100;
let problems = [];
let warnings = [];

// Check last update
const lastUpdate = new Date(repoData.updated_at);
const daysSinceUpdate = (now - lastUpdate) / (1000 * 60 * 60 * 24);

if (daysSinceUpdate > 60) {
  healthScore -= 30;
  problems.push(`No updates in ${Math.floor(daysSinceUpdate)} days - repository may be stale`);
} else if (daysSinceUpdate > 30) {
  healthScore -= 15;
  warnings.push(`No updates in ${Math.floor(daysSinceUpdate)} days - consider checking status`);
}

// Check open issues
if (repoData.open_issues_count > 20) {
  healthScore -= 25;
  problems.push(`High open issues: ${repoData.open_issues_count} - may indicate maintenance burden`);
} else if (repoData.open_issues_count > 10) {
  healthScore -= 10;
  warnings.push(`Moderate open issues: ${repoData.open_issues_count}`);
}

// Check if repo has description
if (!repoData.description || repoData.description.length < 10) {
  healthScore -= 5;
  warnings.push('Missing or minimal repository description');
}

// Check if repo has README
if (!repoData.has_wiki && !repoData.has_pages) {
  healthScore -= 5;
  warnings.push('No wiki or GitHub pages - documentation may be limited');
}

// Analyze commit activity
let commitInfo = 'No recent commits available';
if (commitsData && commitsData.length > 0) {
  const recentCommits = commitsData.slice(0, 5);
  commitInfo = `Last ${recentCommits.length} commits:\n`;
  recentCommits.forEach((commit, idx) => {
    const commitDate = new Date(commit.commit.author.date);
    const daysAgo = Math.floor((now - commitDate) / (1000 * 60 * 60 * 24));
    commitInfo += `  ${idx + 1}. "${commit.commit.message.split('\n')[0].substring(0, 60)}" (${daysAgo} days ago)\n`;
  });
} else {
  healthScore -= 10;
  problems.push('No recent commit history available');
}

// Determine status
let status = 'healthy';
let priority = 'low';

if (healthScore < 50) {
  status = 'critical';
  priority = 'high';
} else if (healthScore < 75) {
  status = 'warning';
  priority = 'medium';
}

// Prepare context for Claude
const claudeContext = `Repository Health Analysis Request:

Repository: ${repoName}
Organization: Ai-Whisperers
Health Score: ${healthScore}/100
Status: ${status}
Priority: ${priority}

Repository Stats:
- Stars: ${repoData.stargazers_count}
- Forks: ${repoData.forks_count}
- Open Issues: ${repoData.open_issues_count}
- Size: ${repoData.size} KB
- Default Branch: ${repoData.default_branch}
- Last Updated: ${Math.floor(daysSinceUpdate)} days ago
- Language: ${repoData.language || 'Not specified'}
- Private: ${repoData.private ? 'Yes' : 'No'}

Problems Identified:
${problems.length > 0 ? problems.map((p, i) => `${i + 1}. ${p}`).join('\n') : 'None'}

Warnings:
${warnings.length > 0 ? warnings.map((w, i) => `${i + 1}. ${w}`).join('\n') : 'None'}

Recent Activity:
${commitInfo}

Description: ${repoData.description || 'No description provided'}`;

return {
  json: {
    repository: repoName,
    health_score: healthScore,
    status: status,
    priority: priority,
    problems: problems,
    warnings: warnings,
    stats: {
      stars: repoData.stargazers_count,
      forks: repoData.forks_count,
      open_issues: repoData.open_issues_count,
      size_kb: repoData.size,
      language: repoData.language,
      days_since_update: Math.floor(daysSinceUpdate)
    },
    claude_context: claudeContext,
    repo_url: repoData.html_url,
    timestamp: now.toISOString()
  }
};

// Extract Claude's analysis and format for email
const inputData = $input.first().json;
const claudeResponse = inputData.content[0].text;

return {
  json: {
    repository: $('Analyze Repository Health').first().json.repository,
    health_score: $('Analyze Repository Health').first().json.health_score,
    status: $('Analyze Repository Health').first().json.status,
    priority: $('Analyze Repository Health').first().json.priority,
    problems: $('Analyze Repository Health').first().json.problems,
    warnings: $('Analyze Repository Health').first().json.warnings,
    stats: $('Analyze Repository Health').first().json.stats,
    repo_url: $('Analyze Repository Health').first().json.repo_url,
    claude_analysis: claudeResponse,
    timestamp: $('Analyze Repository Health').first().json.timestamp
  }
};
